import subprocess, re
files = open('specs/sk-doc/066-skill-readability-refinement/011-system-deep-loop/004-deep-review/scratch/scope.txt').read().split()
def blocks(text):
    out=[]; cur=None; fence=None
    for line in text.splitlines():
        m=re.match(r'^(\s*)(`{3,}|~{3,})(.*)$', line)
        if cur is None and m:
            fence=m.group(2); cur=[line]
        elif cur is not None:
            cur.append(line)
            if m and m.group(2)[0]==fence[0] and len(m.group(2))>=len(fence) and not m.group(3).strip():
                out.append('\n'.join(cur)); cur=None
    if cur: out.append('\n'.join(cur))
    return out
for f in files:
    head=subprocess.check_output(['git','show','HEAD:'+f], text=True)
    now=open(f).read()
    hb=blocks(head); nb=blocks(now)
    if hb!=nb:
        print('CHANGED', f, len(hb), len(nb))
        # print first differing
        for i,(a,b) in enumerate(zip(hb,nb)):
            if a!=b:
                print(' block',i); print('HEAD:',a[:400]); print('NOW:',b[:400]); break
        if len(hb)!=len(nb):
            print(' count mismatch')
